/*selectMasterMpSoUniformGrDetailPopHdList*/
SELECT	BUYER_ITEM_NO,
		ITEM_QTY,
		GR_QTY
FROM	KEP_BUYER_ST_PODT
WHERE	1=1
AND		BUYER = #{buyer}
AND		ST_NO = #{st_no}
AND		ST_SEQ = #{st_seq}

mapper.update:

/*updateMasterMpSoUniformGrDetailPopSum*/
UPDATE	KEP_BUYER_ST_PODT
SET		GR_QTY = GR_QTY + TO_NUMBER(#{gr_qty}),
		CHANGE_DATE = SYSDATE
WHERE	1=1
AND		BUYER = #{buyer}
AND		ST_NO = #{st_no}
AND		ST_SEQ = #{st_seq}
